      ctx.clearRect(0, 0, width, height);
      const spacing = 26;
      // Periodic waves make time=0 and time=24 identical; dot centres never move.
      const phase = time / 24 * Math.PI * 2;
      for (let y = spacing * .5; y < height; y += spacing) {
        for (let x = spacing * .5; x < width; x += spacing) {
          const u = x / Math.max(width, 1), v = y / Math.max(height, 1);
          const field = (
            Math.sin((u * 2.15 + v * .55) * Math.PI * 2 + phase) * .46 +
            Math.cos((u * -.75 + v * 1.45) * Math.PI * 2 - phase * 2) * .3 +
            Math.sin((u * 1.1 - v * 1.7) * Math.PI * 2 + phase * 3) * .18
